function alegriaDeepMerge(target: any, source: any): any {
  if (Array.isArray(source)) return source;
  if (!source || typeof source !== 'object') return target;
  const output: any = Array.isArray(target) ? [...target] : { ...(target || {}) };
  Object.keys(source).forEach((key) => {
    const sourceValue = source[key];
    if (Array.isArray(sourceValue)) {
      output[key] = sourceValue;
    } else if (sourceValue && typeof sourceValue === 'object') {
      output[key] = alegriaDeepMerge(output[key] || {}, sourceValue);
    } else if (sourceValue !== undefined && sourceValue !== null) {
      output[key] = sourceValue;
    }
  });
  return output;
}

['fr', 'en', 'es', 'it', 'de', 'nl', 'ru'].forEach((language) => {
  const fallbackBase = (SITE_CONTENT as any)[language] || (SITE_CONTENT as any).en || (SITE_CONTENT as any).fr || {};
  (SITE_CONTENT as any)[language] = alegriaDeepMerge(fallbackBase, FRONTEND_FIREBASE_I18N_FALLBACK[language] || {});
});
